const keywords = ['reunion', 'reunión', 'representante', 'ppff', 'padre de familia', 'acta pro'];
return items.filter(item => {
  const title = (item.json.summary || '').toLowerCase();
  const desc = (item.json.description || '').toLowerCase();
  return keywords.some(k => title.includes(k) || desc.includes(k)) || title.includes('[acta pro]');
});

// Extrae representante/estudiante/correo con expresiones simples desde
// titulo/descripcion. Este parsing es best-effort para el MVP; en
// Fase 2 estos datos se validaran/completaran con Runachay.
return items.map(item => {
  const e = item.json;
  const desc = e.description || '';
  const emailMatch = desc.match(/[\w.+-]+@[\w-]+\.[a-zA-Z]{2,}/);
  const repMatch = desc.match(/Representante:\s*(.+)/i);
  const studentMatch = desc.match(/Estudiante:\s*(.+)/i);
  return { json: {
    event_id: e.id,
    title: e.summary || '',
    date: (e.start && (e.start.date || e.start.dateTime)) || null,
    start_time: e.start ? e.start.dateTime : null,
    end_time: e.end ? e.end.dateTime : null,
    description: desc,
    teacher_email: (e.organizer && e.organizer.email) || null,
    student_name: studentMatch ? studentMatch[1].trim() : null,
    representative_name: repMatch ? repMatch[1].trim() : null,
    representative_email: emailMatch ? emailMatch[0] : null,
    location: e.location || null,
    video_link: e.hangoutLink || null,
    data_status: (studentMatch && repMatch) ? 'ok' : 'manual_verification_required',
  }};
});

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedEventIds) staticData.processedEventIds = [];
return items.map(item => {
  const isNew = !staticData.processedEventIds.includes(item.json.event_id);
  if (isNew) staticData.processedEventIds.push(item.json.event_id);
  return { json: { ...item.json, is_new: isNew } };
});
